esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // amount: the value we attempt to withdraw from c
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // Do not call deposit to avoid triggering C.deposit's assert in setup.
        // We only observe withdraw behavior given the current state of c.

        // Record balances observable before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule:
        // - If the call reverted: contract balance unchanged and this contract balance unchanged.
        // - If the call succeeded: contract balance decreased by exactly amount and this contract balance did not decrease (it should have increased by at least amount delivered by transfer).
        // Note: avoid underflow in expressions by comparing with >= when appropriate.
        assert(
            (reverted && afterC == beforeC && afterThis == beforeThis)
            || (!reverted && beforeC >= amount && afterC == beforeC - amount && afterThis >= beforeThis + amount)
        );
    }

    receive() external payable {}
}

